import type { SourcedQuote } from './quoteTypes';

/**
 * Original bilingual adaptations of specific passages in primary texts.
 * These are not presented as verbatim quotations. Each reference names the
 * relevant chapter and topic; links lead to the freely readable source text.
 */
type Passage = [reference: string, text: string, tr: string, courage?: boolean];
let nextId = 1;
function passages(
  author: string,
  book: string,
  bookTr: string,
  sourceUrl: string,
  category: 'society' | 'science',
  rows: Passage[],
): SourcedQuote[] {
  return rows.map(([reference, text, tr, courage]) => ({
    id: `thinker-${String(nextId++).padStart(3, '0')}`,
    text,
    tr,
    source: `${author} — ${book}`,
    sourceTr: `${author} — ${bookTr}`,
    sourceUrl,
    reference,
    category,
    kind: 'adaptation' as const,
    ...(courage ? { tags: ['courage', 'fear'] } : {}),
  }));
}

export const THINKER_QUOTES: SourcedQuote[] = [
  ...passages('John Dewey', 'How We Think', 'Nasıl Düşünürüz', 'https://www.gutenberg.org/cache/epub/37423/pg37423-images.html', 'society', [
    ['I, §4: perplexity as the origin of thought', 'Being puzzled need not end your inquiry. The very thing that unsettles you can give your thinking a question worth pursuing.', 'Kafanın karışması araştırmanın sonu değildir. Seni huzursuz eden şey, düşüncene peşinden gitmeye değer bir soru verebilir.', true],
    ['VI, step 2: defining the difficulty', 'Before a complicated situation overwhelms you, look closely enough to name the actual difficulty. A clear problem gives inquiry a direction.', 'Karmaşık bir durum gözünde büyümeden, asıl güçlüğün adını koyacak kadar dikkatle bak. Açık bir sorun, araştırmaya yön verir.', true],
    ['I, §4: suspended judgment', 'You may leave a question open while you gather evidence. Enduring uncertainty is sometimes the honest work that understanding requires.', 'Kanıt toplarken bir soruyu açık bırakabilirsin. Belirsizliğe dayanmak, bazen anlamanın gerektirdiği dürüst emeğin ta kendisidir.', true],
    ['VI, step 3: alternative suggestions', 'Give a difficult question more than one possible answer. Keeping alternatives alive protects you from mistaking the first idea for the only way.', 'Zor bir soruya birden fazla yanıt düşün. Seçenekleri açık tutmak, ilk fikri tek çıkış yolu sanmanı önler.', true],
    ['VI, step 5: experimental testing', 'Let a small experiment question your prediction. What actually happens can guide you more reliably than how convincing the prediction first sounded.', 'Küçük bir deneme, tahminini sınasın. Gerçekte olanlar, tahmininin başta ne kadar ikna edici göründüğünden daha sağlam yol gösterebilir.'],
    ['VI, step 5: revising conclusions', 'A conclusion can serve you today and still be revised tomorrow. New evidence is an invitation to understand more, not a personal defeat.', 'Bir sonuç bugün işine yarayıp yarın değişebilir. Yeni kanıt, kişisel bir yenilgi değil, daha iyi anlama davetidir.', true],
    ['III, §1: curiosity and new contacts', 'Let curiosity bring you into contact with unfamiliar things. A mind that explores has more experience to draw upon when a difficulty arrives.', 'Merakın seni yabancı olduğun şeylerle tanıştırsın. Keşfeden bir zihin, güçlük geldiğinde başvurabileceği daha çok deneyim biriktirir.'],
    ['III, §1: intellectual curiosity', 'Do not put a worthwhile question away merely because you have asked it. Carry it with you and notice what might help answer it.', 'Değerli bir soruyu yalnızca sormuş olmakla rafa kaldırma. Onu aklında taşı; yanıtına katkı sunabilecek şeyleri fark et.'],
    ['III, §1: protecting wonder', 'Protect the wonder that routine can wear down. Familiarity need not close your eyes to a fresh question about an ordinary thing.', 'Alışkanlığın köreltebildiği hayret duygunu koru. Bir şeye aşina olmak, onun hakkında yeni bir soru sormana engel olmasın.'],
    ['III, §2: depth rather than speed of suggestion', 'A quick answer is not the only sign of ability. Give a question time to sink in; depth can matter more than speed.', 'Yetenek yalnızca hızlı cevap vermek değildir. Sorunun içine işlemesine zaman tanı; düşüncenin derinliği hızından daha değerli olabilir.', true],
    ['I, §1: consecutive reflective thought', 'Allow one sound thought to prepare the next. Understanding grows when your ideas support one another instead of merely crowding your mind.', 'Sağlam bir düşünce bir sonrakine zemin hazırlasın. Fikirlerin zihninde yığılmak yerine birbirini desteklediğinde anlayışın da derinleşir.'],
    ['I, §1: grounds and consequences of belief', 'Ask both what supports your belief and where it leads. Caring about these two questions makes conviction more thoughtful and responsible.', 'Düşünceni neyin desteklediğini ve seni nereye götürdüğünü birlikte sor. Bu iki soruyu önemsemek, kanaatini daha bilinçli ve sorumlu kılar.'],
    ['I, §4: drawing on analogous experience', 'When a problem feels shapeless, recall a situation you have already understood. A useful resemblance can turn confusion into a tentative plan.', 'Bir sorun belirsiz görünüyorsa daha önce anladığın benzer bir durumu hatırla. İşe yarayan bir benzerlik, karmaşadan taslak bir plan çıkarabilir.', true],
    ['XVI: balance of playfulness and seriousness', 'You can be playful with possibilities and serious about finding truth. Curiosity and care belong together in a mind that keeps growing.', 'Olasılıklarla özgürce oynarken gerçeği ciddiyetle arayabilirsin. Büyümeyi sürdüren bir zihinde merak ve özen birbirine eşlik eder.'],
    ['XVI: enriching the present', 'Attend to what makes this present experience meaningful. The present can hold rich possibilities without being swallowed by worry about distant results.', 'Şu an yaşadığın deneyimi anlamlı kılan şeye dikkat et. Bugün, uzak sonuçların kaygısına kapılmadan da zengin olasılıklar taşıyabilir.', true],
    ['XVI: work, drudgery, and valued ends', 'An unappealing task can borrow meaning from a purpose you value. Remember what it serves while you are doing it.', 'Sıkıcı görünen bir iş, değer verdiğin amaçtan anlam alabilir. Onu yaparken neye hizmet ettiğini yeniden hatırla.'],
    ['XV: responsibility for a reasonable case', 'Give your own idea a fair explanation instead of waiting to guess the approved answer. Taking responsibility for your reasons strengthens independent thought.', 'Onaylanacak cevabı tahmin etmeyi beklemek yerine kendi fikrini gerekçelendir. Nedenlerinin sorumluluğunu almak, bağımsız düşünceni güçlendirir.', true],
    ['XV: stopping and thinking', 'Leave a pause in which thought can gather itself. Reflection needs a little freedom from the demands that keep pulling you elsewhere.', 'Düşüncenin toparlanabileceği bir duraklamaya yer aç. Düşünmek, seni başka yöne çeken taleplerden bir süre uzaklaşmayı gerektirir.'],
    ['VI, step 3: enterprising and cautious inference', 'Exploring a possibility takes a small intellectual leap. You can be adventurous in asking and careful in checking at the same time.', 'Bir olasılığı araştırmak zihinsel bir cesaret ister. Soru sorarken girişken, yanıtı denetlerken dikkatli olabilirsin; bu ikisi birbiriyle uyumludur.', true],
    ['IV: skill acquired with intelligence', 'Practice a skill with understanding, not only repetition. When you know what your action means, you can use it more intelligently in new situations.', 'Bir beceriyi yalnızca tekrarla değil, anlayarak çalış. Yaptığının anlamını bildiğinde onu yeni durumlarda daha bilinçli kullanabilirsin.'],
  ]),
  ...passages('William James', 'Talks to Teachers and Students', 'Öğretmenlere ve Öğrencilere Konuşmalar', 'https://www.gutenberg.org/files/16287/16287-h/16287-h.htm', 'science', [
    ['VIII: virtues as habits', 'Courage is among the qualities that can become habitual. It is worth noticing the everyday occasions on which you already practice it.', 'Cesaret de alışkanlık kazanabilen niteliklerdendir. Günlük hayatında onu zaten kullandığın küçük anları fark etmeye değer.', true],
    ['VIII: freeing higher powers through useful routines', 'Settle the ordinary details of your day into useful routines. Your mind then has more room for the work that truly requires judgment.', 'Günün sıradan ayrıntılarını işe yarayan bir düzene yerleştir. Böylece zihninde gerçekten değerlendirme isteyen işlere daha fazla yer açılır.'],
    ['VIII: supporting a new resolution', 'Surround a new resolution with practical support: suitable circumstances, helpful commitments, and people who make the new direction easier to follow.', 'Yeni kararının çevresine somut destekler kur: uygun koşullar, yardımcı sorumluluklar ve seçtiğin yönde ilerlemeyi kolaylaştıran insanlar olsun.'],
    ['VIII: daily exercise of effort', 'Practice meeting a manageable difficulty before a demanding day arrives. Familiarity with effort can help you stand more steadily when courage is needed.', 'Zorlu gün gelmeden, baş edebileceğin bir güçlükle çalış. Çabaya alışmak, cesaret gerektiğinde daha sağlam durmana yardımcı olabilir.', true],
    ['VIII: new motives and new habits', 'Old habits do not make a new life impossible. A lasting new motive can reorganize what you repeatedly choose to do.', 'Eski alışkanlıkların, yeni bir hayatı imkânsız kılmaz. Kalıcı bir yeni amaç, tekrar tekrar seçtiğin davranışları yeniden düzenleyebilir.', true],
    ['VIII: competence develops through particulars', 'The details of learning may feel ordinary while your judgment is quietly improving. Do not demand the final shape of your ability too soon.', 'Öğrenmenin ayrıntıları sıradan görünürken değerlendirme gücün sessizce gelişebilir. Yeteneğinin son biçimini kendinden hemen bekleme.', true],
    ['VII: the spectacle of effort', 'Another person’s wholehearted effort can awaken effort in you. Seek company whose way of working makes you want to take part.', 'Bir başkasının içten çabası senin çabanı da uyandırabilir. Çalışma biçimi sana katılma isteği veren insanlara yakın dur.'],
    ['XI: attention and new aspects', 'If your attention wanders, ask a fresh question about the subject. A new angle can make a familiar task interesting again.', 'Dikkatin dağılıyorsa konuya yeni bir soru sor. Farklı bir açı, alıştığın işi yeniden ilgi çekici hale getirebilir.'],
    ['XI: the dot experiment', 'Look more closely instead of merely staring harder. Asking about shape, distance, or relation gives attention something definite to do.', 'Yalnızca daha sıkı odaklanmaya çalışmak yerine ayrıntılara bak. Biçimi, uzaklığı veya ilişkileri sormak, dikkatine somut bir iş verir.'],
    ['The Gospel of Relaxation: action and feeling', 'When fear is present, consider the action still within your control. A deliberate act of courage can come before the feeling of courage.', 'Korku varken hâlâ kontrol edebildiğin davranışı düşün. Bilinçli bir cesaret davranışı, kendini cesur hissetmenden önce gelebilir.', true],
    ['The Gospel of Relaxation: restraint before regretted words', 'Pause before the hurtful word escapes. Regulating what you express can give an agitated feeling room to become calmer.', 'Kırıcı söz ağzından çıkmadan durakla. Dışarıya yansıttığın davranışı düzenlemek, kabaran duygunun sakinleşmesine alan açabilir.', true],
    ['The Gospel of Relaxation: kindness in conduct', 'A friendly question or a shared laugh can soften an unfriendly relationship. Sometimes warmth begins in what you do together.', 'İçten bir soru ya da birlikte gülmek, soğuk bir ilişkiyi yumuşatabilir. Bazen yakınlık, birlikte yaptığınız küçük bir şeyle başlar.'],
    ['The Gospel of Relaxation: calm as an ideal', 'You need not admire hurry as a sign of importance. Calm, dignity, and ease are also qualities a working life can cultivate.', 'Telaşı önem göstergesi saymak zorunda değilsin. Çalışan bir hayatın içinde sakinlik, vakar ve rahatlık da geliştirilebilir.', true],
    ['The Gospel of Relaxation: example and imitation', 'Your calm manner can offer someone else a model. A quieter way of meeting the day may travel farther than you notice.', 'Sakin tavrın bir başkasına örnek olabilir. Günü daha huzurlu karşılama biçimin, sen fark etmeden çevrene yayılabilir.'],
    ['The Gospel of Relaxation: execution after decision', 'Once you have considered your plan, let execution have your attention. Continually rehearsing the outcome can interrupt the work itself.', 'Planını değerlendirdikten sonra dikkatini uygulamaya ver. Sonucu zihninde durmadan prova etmek, yapmakta olduğun işi kesintiye uğratabilir.', true],
    ['The Gospel of Relaxation: preparation and spontaneity', 'Know your subject well, then leave room for a natural response. Preparation can support spontaneity instead of making every moment rigid.', 'Konuna iyi hazırlan, ardından doğal davranmaya yer bırak. Hazırlık, her anı katılaştırmak yerine kendiliğindenliği destekleyebilir.', true],
    ['On a Certain Blindness: limitations of outside judgment', 'A life that looks unremarkable from outside may hold deep meaning within. Meet another person with curiosity before deciding what matters to them.', 'Dışarıdan sıradan görünen bir hayat, içinde derin anlamlar taşıyabilir. Bir insan için neyin değerli olduğuna karar vermeden önce onu merakla dinle.'],
    ['What Makes a Life Significant: heroism in common toil', 'Courage is present in ordinary labor as well as famous adventures. Look with respect at the patient work that keeps daily life going.', 'Cesaret, ünlü serüvenlerde olduğu kadar sıradan emekte de vardır. Günlük hayatı ayakta tutan sabırlı işe saygıyla bak.', true],
    ['What Makes a Life Significant: ideals joined to endurance', 'An ideal gains living significance when someone bears effort for it. Let what you value meet the patience and care of your actual day.', 'Bir ideal, uğrunda emek verildiğinde yaşayan bir anlam kazanır. Değer verdiğin şey, gününün sabrı ve özeniyle buluşsun.'],
    ['What Makes a Life Significant: meaning across circumstances', 'Meaning can be alive in circumstances unlike your own. Remembering this can soften the fear and hostility with which people sometimes meet one another.', 'Anlam, seninkinden farklı koşullarda da yaşayabilir. Bunu hatırlamak, insanların birbirine duyduğu korkuyu ve sertliği yumuşatabilir.', true],
  ]),
  ...passages('Charles Darwin', 'Autobiography', 'Otobiyografi', 'https://www.gutenberg.org/cache/epub/2010/pg2010-images.html', 'science', [
    ['Work on the Origin: observations contrary to a theory', 'Write down the observation that challenges your preferred explanation. Giving inconvenient evidence a place is a strength of honest inquiry.', 'Sevdiğin açıklamaya karşı çıkan gözlemi de yaz. Hoşuna gitmeyen kanıta yer vermek, dürüst araştırmanın güçlü yanıdır.', true],
    ['Work on the Origin: reducing the manuscript', 'A smaller, carefully chosen account can carry an idea farther than an enormous one. Give your strongest evidence space to be understood.', 'Özenle seçilmiş kısa bir anlatım, fikri dev bir metinden daha uzağa taşıyabilir. En güçlü kanıtlarının anlaşılmasına alan aç.'],
    ['Work on the Origin: criticism and conscientious work', 'When criticism hurts, remember the care you actually gave the work. Others’ judgments do not erase the honest effort you know you made.', 'Eleştiri canını acıttığında işine verdiğin gerçek özeni hatırla. Başkalarının yargıları, ortaya koyduğunu bildiğin dürüst emeği silemez.', true],
    ['Work on the Origin: avoiding unproductive controversy', 'Not every disagreement deserves your working hours. You may leave an unproductive controversy and return to the question you came to investigate.', 'Her anlaşmazlık çalışma saatlerini hak etmez. Verimsiz bir tartışmadan ayrılıp araştırmak için yola çıktığın soruya dönebilirsin.', true],
    ['Orchids: a focused contribution', 'Choose one part of a large subject and study it carefully. A well-made contribution can invite others to carry the inquiry beyond you.', 'Büyük bir konunun bir bölümünü seç ve özenle incele. İyi yapılmış bir katkı, başkalarını araştırmayı daha ileri taşımaya davet edebilir.'],
    ['Earthworms: returning to an old question', 'An old question may still deserve your attention. Returning to it after many years can connect today’s curiosity with work you once began.', 'Eski bir soru hâlâ dikkatini hak ediyor olabilir. Yıllar sonra ona dönmek, bugünkü merakını bir zamanlar başladığın işe bağlayabilir.'],
    ['Reflections on writing: difficulty and clarity', 'Struggling to express an idea clearly can reveal a weakness in the reasoning. Revision is also a way of discovering what you truly mean.', 'Bir fikri açık anlatmakta zorlanmak, düşüncedeki bir boşluğu gösterebilir. Düzeltmek, gerçekten ne demek istediğini keşfetmenin de bir yoludur.'],
    ['Reflections on writing: rough draft before correction', 'Let the rough draft be rough, then revise with care. Trying to perfect every sentence before writing it can obstruct the thought taking shape.', 'İlk taslağın kusurlu olmasına izin ver; sonra özenle düzelt. Her cümleyi yazmadan kusursuzlaştırmaya çalışmak, düşüncenin biçimlenmesini engelleyebilir.', true],
    ['Reflections on writing: expanding an outline', 'Begin a large piece of writing with a few guiding headings. Expand and rearrange them until the material finds a shape you can follow.', 'Büyük bir yazıya birkaç yol gösterici başlıkla yaklaş. Malzeme izleyebileceğin bir biçim bulana kadar başlıkları genişlet ve yeniden düzenle.'],
    ['Working methods: classified notes and indexes', 'Keep your observations where you can find them again. A modest system of notes lets past effort become available for a new question.', 'Gözlemlerini yeniden bulabileceğin yerde sakla. Mütevazı bir not düzeni, geçmişteki emeğini yeni bir soru için kullanılabilir kılar.'],
    ['Reflections on aesthetic tastes', 'Give poetry, music, or beauty an actual place in your life. An interest you value also needs occasions on which to be enjoyed.', 'Şiire, müziğe ya da güzelliğe hayatında gerçek bir yer aç. Değer verdiğin bir ilginin, yaşanacağı zamanlara da ihtiyacı vardır.'],
    ['Self-assessment: speed of understanding', 'Understanding slowly need not keep you from useful work. Careful observation and sustained interest can matter alongside quickness of mind.', 'Yavaş anlamak, değerli iş yapmana engel olmak zorunda değildir. Dikkatli gözlem ve kalıcı ilgi de zihnin hızı kadar önem taşıyabilir.', true],
    ['Self-assessment: noticing what escapes attention', 'Something easily overlooked may be worth examining closely. The desire to understand ordinary observations can sustain a meaningful scientific life.', 'Kolayca gözden kaçan bir şey, yakından incelenmeye değer olabilir. Sıradan gözlemleri anlama isteği, anlamlı bir bilim hayatını besleyebilir.'],
    ['Self-assessment: relinquishing a cherished hypothesis', 'You may care deeply about an explanation and still release it when the evidence changes. Loyalty to inquiry can be stronger than attachment to an answer.', 'Bir açıklamayı çok sevip kanıt değiştiğinde yine de bırakabilirsin. Araştırmaya bağlılık, bir cevaba duyduğun bağlılıktan daha güçlü olabilir.', true],
    ['Self-assessment: excessive skepticism can deter experiments', 'Let caution examine a possibility without closing the door too early. Some useful experiments are lost when doubt prevents the attempt altogether.', 'Temkin, bir olasılığı incelesin ama kapıyı erkenden kapatmasın. Kuşku denemeyi tümüyle önlediğinde işe yarayabilecek araştırmalar da kaybolabilir.', true],
  ]),
  ...passages('Jane Addams', 'Democracy and Social Ethics', 'Demokrasi ve Toplumsal Etik', 'https://www.gutenberg.org/files/15487/15487-h/15487-h.htm', 'society', [
    ['I: a contemporary standard of responsibility', 'What counted as enough yesterday may not meet today’s responsibility. Let your sense of duty grow with your understanding of other people’s lives.', 'Dün yeterli olan, bugünün sorumluluğuna yetmeyebilir. Görev anlayışın, başkalarının hayatını anladıkça büyüsün.'],
    ['I: social obligation beyond the household', 'Care can reach beyond the people already close to you. Notice one human need outside your familiar circle and consider your part in answering it.', 'Özenin, zaten yakın olduğun insanların ötesine uzanabilir. Alıştığın çevrenin dışındaki bir ihtiyacı fark et; karşılanmasındaki payını düşün.'],
    ['I: shared experience as a source of social motive', 'If you want a wider purpose, seek a wider acquaintance with life. Shared experience can give responsibility a warmth that abstract rules cannot supply.', 'Daha geniş bir amaç arıyorsan hayatı daha geniş tanı. Paylaşılan deneyim, sorumluluğa soyut kuralların veremediği bir sıcaklık katabilir.'],
    ['I: processes as well as results', 'A generous aim also needs a fitting method. Pay attention to how you help, because a good intention alone does not settle the outcome.', 'Cömert bir amaç, uygun bir yöntem de ister. Nasıl yardım ettiğine dikkat et; iyi niyet tek başına sonucu belirlemez.'],
    ['I: seeing the size of one another’s burdens', 'Walk close enough to others to see what they carry. Understanding a burden begins with leaving the comfort of a distant judgment.', 'İnsanların taşıdığı yükü görebilecek kadar yanlarına yaklaş. Bir yükü anlamak, uzaktan hüküm vermenin rahatlığından çıkmakla başlar.'],
    ['I: experience as a corrective to social opinions', 'Let real encounters correct an easy opinion about people. A humbler judgment can be the beginning of more useful service.', 'İnsanlar hakkındaki kolay yargını gerçek karşılaşmalar düzeltsin. Daha alçakgönüllü bir değerlendirme, daha yararlı bir hizmetin başlangıcı olabilir.'],
    ['I: imagination and understanding another’s experience', 'Use imagination to approach an experience you have not lived. The ability to picture another life can soften the hardness of your response.', 'Yaşamadığın bir deneyime yaklaşmak için hayal gücünü kullan. Başkasının hayatını zihninde canlandırabilmek, tepkindeki sertliği yumuşatabilir.'],
    ['I: narrow circles and the scope of ethics', 'Keep your circle from becoming a wall. Respect grows richer when it makes room for people unlike those you already understand.', 'Çevrenin bir duvara dönüşmesine izin verme. Saygı, zaten anladığın insanlardan farklı olanlara da yer açtığında zenginleşir.'],
    ['II: charitable effort and unequal standards', 'Help without treating good fortune as proof of greater worth. A person’s need does not place their dignity below yours.', 'İyi koşullarda yaşamayı üstünlük kanıtı saymadan yardım et. Bir insanın ihtiyaç içinde olması, onurunu seninkinden aşağıya koymaz.'],
    ['VI: education grounded in actual work', 'Your everyday work contains material for learning. Ask what knowledge would give the actions you already perform a larger meaning.', 'Her gün yaptığın işte öğrenilecek malzeme vardır. Zaten yaptığın davranışlara hangi bilginin daha geniş anlam katacağını sor.'],
    ['VI: tools as a social inheritance', 'The tools in your hands carry earlier people’s work. Understanding that inheritance can connect your daily task to a longer human story.', 'Elindeki araçlar, senden önceki insanların emeğini taşır. Bu mirası anlamak, günlük işini daha uzun bir insanlık hikâyesine bağlayabilir.'],
    ['VI: road builders and a shared purpose', 'People doing different parts of a task need to understand the whole. Shared purpose grows when everyone can see where the work is going.', 'Bir işin farklı parçalarını yapanlar bütünü de anlamaya ihtiyaç duyar. Herkes işin nereye gittiğini gördüğünde ortak amaç güçlenir.'],
    ['VI: education as an offset to over-specialization', 'A narrow occupation need not become a narrow life. Give yourself knowledge that helps you participate as a thoughtful member of society.', 'Dar bir uzmanlık, dar bir hayata dönüşmek zorunda değildir. Topluma bilinçli biçimde katılmanı sağlayan bilgilere kendinde yer aç.'],
    ['VII: interconnected ethical development', 'The moral life of a community connects its different parts. What we excuse for ourselves can shape what becomes acceptable around us.', 'Bir toplumun ahlaki hayatı, farklı kesimlerini birbirine bağlar. Kendimiz için mazur gördüklerimiz, çevremizde kabul edilir olanı da biçimlendirebilir.'],
    ['VII: the educative power of responsibility', 'Trust people with a meaningful share of responsibility. Taking part in meeting a real need can itself become an education.', 'İnsanlara anlamlı bir sorumluluk payı ver. Gerçek bir ihtiyacın karşılanmasına katılmak, başlı başına bir öğrenme deneyimi olabilir.'],
  ]),
  ...passages('W. E. B. Du Bois', 'The Souls of Black Folk', 'Siyah Halkın Ruhları', 'https://www.gutenberg.org/files/408/408-h/408-h.htm', 'society', [
    ['I: double consciousness and the wish for an undivided self', 'Do not let a contemptuous gaze become your only measure of yourself. A person deserves room to live without disowning their own inheritance.', 'Seni küçümseyen bakış, kendini ölçtüğün tek ölçü olmasın. İnsan, kendi köklerini inkâr etmeden yaşayabileceği bir alanı hak eder.', true],
    ['I: work, culture, and liberty together', 'Work, learning, and freedom can support one another. A fuller life need not sacrifice the growth of the mind to the demands of earning.', 'Emek, öğrenme ve özgürlük birbirini destekleyebilir. Daha bütünlüklü bir hayat, geçim uğruna zihnin gelişiminden vazgeçmek zorunda değildir.'],
    ['V: foundations of knowledge', 'Build learning on foundations deep enough to support it. Haste in laying those foundations can leave an impressive name standing over fragile work.', 'Öğrenmeni taşıyacak kadar derin temeller kur. Temeli aceleye getirmek, gösterişli bir adın altında kırılgan bir iş bırakabilir.'],
    ['V: the university and real life', 'Let growing knowledge meet the problems of actual life. Education gains purpose when understanding helps us respond more wisely to the world around us.', 'Gelişen bilgi, gerçek hayatın sorunlarıyla buluşsun. Anlamak, çevremize daha bilinçli karşılık vermemizi sağladığında eğitim amaç kazanır.'],
    ['VI: teachers and the contact of living souls', 'A teacher gives more than information when they offer sincere companionship. Learning can grow through the human connection of working and hoping together.', 'Bir öğretmen içten bir yakınlık sunduğunda bilgiden fazlasını verir. Öğrenme, birlikte çalışmanın ve umut etmenin insani bağıyla büyüyebilir.'],
    ['VI: respect for the sovereign human soul', 'Make room for a person to think and work in their own way. An unfamiliar inner life may offer everyone a perspective they lacked.', 'Bir insanın kendi yolunca düşünüp çalışmasına yer aç. Tanımadığın bir iç dünya, herkese eksik kalan bir bakış sunabilir.'],
    ['VI: cooperative striving toward a larger civilization', 'Past wrongs deserve recognition, while the future also needs our effort. A shared commitment to a larger human life can give that effort direction.', 'Geçmişteki haksızlıklar görülmeyi hak eder; gelecek de emeğimizi bekler. Daha insanca bir hayata ortak bağlılık, bu emeğe yön verebilir.'],
    ['XIV: hope within the Sorrow Songs', 'Sorrow and hope can inhabit the same song. Even wounded voices can keep alive a faith that people will one day be judged justly.', 'Hüzün ve umut aynı ezgide yaşayabilir. Yaralı sesler de insanların bir gün adaletle değerlendirileceğine duyulan inancı diri tutabilir.', true],
    ['XIV: uncertainty about the limits of human development', 'Do not turn today’s unequal opportunities into a verdict on human possibility. We do not know enough to declare another people’s future closed.', 'Bugünün eşitsiz fırsatlarını insanın imkânları hakkında son hükme çevirme. Başka insanların geleceğini kapatacak kadar çok şey bilmiyoruz.', true],
    ['XIV: the gifts of story, labor, and spirit', 'A community contributes through its stories, its labor, and its moral voice. Recognizing those gifts is part of seeing one another fully.', 'Bir topluluk hikâyeleriyle, emeğiyle ve ahlaki sesiyle katkıda bulunur. Bu armağanları tanımak, birbirimizi bütünüyle görmenin bir parçasıdır.'],
  ]),
  ...passages('Michael Faraday', 'The Chemical History of a Candle', 'Bir Mumun Kimyasal Tarihi', 'https://www.gutenberg.org/cache/epub/14474/pg14474-images.html', 'science', [
    ['Lecture I: a candle as an entrance to natural philosophy', 'An ordinary object can open a serious inquiry. You do not always need a novel subject to discover how richly the world is connected.', 'Sıradan bir nesne, ciddi bir araştırmanın kapısını açabilir. Dünyanın zengin bağlantılarını keşfetmek için her zaman yepyeni bir konu gerekmez.'],
    ['Lecture I: speaking familiarly to young listeners', 'Knowledge can speak simply without losing its seriousness. Meeting a learner where they are is a generous part of explaining well.', 'Bilgi, ciddiyetini kaybetmeden sade konuşabilir. Öğrenenin bulunduğu yere yaklaşmak, iyi anlatmanın cömert bir parçasıdır.'],
    ['Lecture I: irregular candle burning as instruction', 'An unexpected result deserves investigation before dismissal. The irregular behavior of a simple candle can reveal something a perfect performance would hide.', 'Beklenmedik sonuç, gözden çıkarılmadan önce incelenmeyi hak eder. Basit bir mumun düzensiz yanışı bile kusursuz görünümün gizlediği bir şeyi gösterebilir.'],
    ['Lecture I: asking why a new result occurs', 'When something new happens, turn surprise into a question about its cause. Let wonder lead you toward an explanation you can examine.', 'Yeni bir şey olduğunda şaşkınlığını nedenini araştıran bir soruya çevir. Hayretin, inceleyebileceğin bir açıklamaya doğru seni götürsün.'],
    ['Lecture I: the name of capillary attraction', 'An unfamiliar scientific name need not stop you. Look at the action it describes; understanding a phenomenon matters more than being impressed by its label.', 'Yabancı bir bilimsel ad seni durdurmasın. Anlattığı işleyişe bak; olayı anlamak, etiketinden etkilenmekten daha değerlidir.', true],
    ['Lecture I: rapidly changing shapes of flame', 'What appears to happen all at once may be a quick succession of events. Patient observation can distinguish what a first glance blends together.', 'Aynı anda oluyor gibi görünen şey, hızla art arda gelişen olaylar olabilir. Sabırlı gözlem, ilk bakışın birleştirdiğini ayırt edebilir.'],
    ['Lecture II: following the products of combustion', 'Ask where the material goes when a familiar change occurs. Following the process can turn a disappearing candle into a lesson in careful explanation.', 'Tanıdık bir değişimde maddenin nereye gittiğini sor. Süreci izlemek, tükenen bir mumu bile dikkatli açıklama kurmanın dersine çevirebilir.'],
    ['Lecture V: weighing air and checking the balance again', 'Give a surprising measurement a check you can repeat. Returning the apparatus to its starting condition helps show what your experiment has established.', 'Şaşırtıcı bir ölçümü tekrarlanabilir biçimde denetle. Düzeneği başlangıç koşuluna döndürmek, deneyinin neyi ortaya koyduğunu anlamaya yardım eder.'],
    ['Lecture VI: simplifying the steps of demonstration', 'Explain a difficult process through steps that can be followed. A simple demonstration can make the reasoning visible instead of asking for blind acceptance.', 'Zor bir süreci izlenebilir adımlarla açıkla. Sade bir gösterim, körü körüne kabul istemek yerine düşüncenin nasıl ilerlediğini görünür kılabilir.'],
    ['Lecture VI: relations between animal and plant life', 'Attend to the connections between forms of life. The relations among air, plants, and animals remind us that our existence is not isolated.', 'Canlılık biçimleri arasındaki bağlara dikkat et. Hava, bitkiler ve hayvanlar arasındaki ilişkiler, varlığımızın tek başına olmadığını hatırlatır.'],
  ]),
  ...passages('Henri Poincaré', 'The Foundations of Science', 'Bilimin Temelleri', 'https://www.gutenberg.org/files/39713/39713-h/39713-h.htm', 'science', [
    ['Science and Method, Introduction: finite time and choice', 'You cannot observe everything, and you do not have to. Choosing a worthwhile question is part of doing careful work with the time available.', 'Her şeyi gözlemleyemezsin; buna mecbur da değilsin. Değerli bir soru seçmek, elindeki zamanla özenli çalışmanın bir parçasıdır.'],
    ['Science and Method, Introduction: errors of instruments and senses', 'Remember that observation has limits. Allowing for the imperfections of your tools makes your conclusions more careful, not your work less valuable.', 'Gözlemin sınırları olduğunu hatırla. Araçlarının kusurlarını hesaba katmak, işini değersizleştirmez; sonuçlarını daha dikkatli kurmanı sağlar.'],
    ['Science and Method, Introduction: historical development of new ideas', 'An unfamiliar idea can become less intimidating when you trace how it arose. Its history may supply the steps that a finished explanation leaves hidden.', 'Yabancı bir fikir, nasıl doğduğunu izlediğinde daha az ürkütücü gelebilir. Tarihi, hazır açıklamanın gizlediği ara adımları görünür kılabilir.', true],
    ['Science and Method, Introduction: geodesy and a new decimal', 'A small gain in accuracy may contain enormous care. Respect the patient work behind the detail that looks insignificant from a distance.', 'Doğrulukta küçük bir artış, büyük bir özen taşıyabilir. Uzaktan önemsiz görünen ayrıntının arkasındaki sabırlı emeğe saygı duy.'],
    ['Science and Method, I.1: discovery before practical application', 'A question need not promise an immediate reward to deserve study. Knowledge pursued with curiosity can later make unforeseen work possible.', 'Bir soru, araştırılmaya değer olmak için hemen ödül vaat etmek zorunda değildir. Merakla aranan bilgi, sonradan öngörülmemiş işleri mümkün kılabilir.'],
    ['Science and Method, I.1: facts that can serve repeatedly', 'Look for an understanding that can help you more than once. Recognizing a recurring relation gives one experience value beyond its original setting.', 'Sana birden fazla kez yardım edebilecek bir anlayış ara. Tekrarlanan bir ilişkiyi fark etmek, deneyime ilk bağlamının ötesinde değer kazandırır.'],
    ['Science and Method, I.1: exceptions after a rule is established', 'Once a pattern seems familiar, notice the case that does not fit. An exception may teach what another confirmation can no longer show.', 'Bir örüntü tanıdık hale geldiğinde ona uymayan durumu fark et. Bir istisna, yeni bir doğrulamanın artık gösteremediğini öğretebilir.'],
    ['Science and Method, I.1: distant phenomena illuminate nearby ones', 'Studying something far from your immediate concerns can sharpen your view of home. A distant example sometimes makes a nearby difficulty clearer.', 'Günlük ilgilerinden uzak bir konuyu incelemek, yakınına bakışını keskinleştirebilir. Uzak bir örnek, bazen yanı başındaki güçlüğü daha anlaşılır kılar.'],
    ['Science and Method, I.1: likeness beneath apparent divergence', 'Look for a relationship beneath the differences. Things that first seem unrelated can reveal a common structure when considered with care.', 'Farklılıkların altında bir ilişki ara. İlk bakışta ilgisiz görünen şeyler, özenle düşünüldüğünde ortak bir yapı gösterebilir.'],
    ['Science and Hypothesis, IX: facts and the house of science', 'Collected facts need an intelligible arrangement. As stones need structure to become a house, information needs relationships to become understanding.', 'Toplanan bilgiler anlaşılır bir düzene ihtiyaç duyar. Taşların eve dönüşmek için yapıya ihtiyacı olduğu gibi, bilgi de anlayışa dönüşmek için bağlara ihtiyaç duyar.'],
    ['Science and Method, I.1: delight in the beauty of nature', 'Let the beauty of an intelligible world sustain your curiosity. The pleasure of understanding can accompany work whose rewards are not immediately visible.', 'Anlaşılabilir bir dünyanın güzelliği merakını beslesin. Anlamanın sevinci, karşılığı hemen görünmeyen bir çalışmaya da eşlik edebilir.'],
    ['Science and Method, I.3: invention as discernment and choice', 'Creating involves choosing among possibilities, not simply producing more of them. Give attention to the combination that reveals something useful.', 'Yaratmak, yalnızca daha çok olasılık üretmek değil, aralarından seçim yapmaktır. İşe yarayan bir şeyi açığa çıkaran birleşime dikkat ver.'],
    ['Science and Method, I.3: fertile combinations from distant domains', 'A fruitful idea may join elements from distant fields. Explore the connection carefully; difference is promising when it reveals a real relationship.', 'Verimli bir fikir, uzak alanlardan gelen öğeleri birleştirebilir. Bağlantıyı dikkatle araştır; farklılık, gerçek bir ilişkiyi gösterdiğinde umut vericidir.'],
    ['Science and Method, I.3: fifteen days without a result', 'Several days without a result need not settle the value of an inquiry. Difficult discovery can include long stretches with little visible progress.', 'Günlerce sonuç alamamak, araştırmanın değerini kesinleştirmez. Zor bir keşfin içinde görünür ilerlemenin az olduğu uzun dönemler bulunabilir.', true],
    ['Science and Method, I.3: the seaside interruption', 'After sustained effort, a change of surroundings can make room for a new connection. Returning with a different perspective is still part of inquiry.', 'Yoğun çabanın ardından ortam değişikliği, yeni bir bağlantıya yer açabilir. Farklı bir bakışla geri dönmek de araştırmanın parçasıdır.'],
    ['Science and Method, I.3: effort clarifying the remaining difficulty', 'An attempt may be useful because it shows exactly what remains difficult. A clearer obstacle is itself information for the next stage of work.', 'Bir girişim, neyin hâlâ zor olduğunu gösterdiği için yararlı olabilir. Engeli daha açık görmek, çalışmanın sonraki aşaması için bilgidir.', true],
    ['Science and Method, I.3: preparation preceding inspiration', 'An apparently sudden insight may have a long preparation behind it. Do not discount earlier effort merely because its usefulness was hidden at the time.', 'Ansızın gelen bir kavrayışın arkasında uzun bir hazırlık olabilir. Yararı o sırada görünmedi diye önceki emeğini değersiz sayma.'],
    ['Science and Method, I.3: verification after certainty', 'A powerful feeling of certainty is still worth checking. Verification can protect a promising idea from the mistakes that excitement overlooks.', 'Güçlü bir kesinlik hissi de denetlenmeye değer. Doğrulama, umut veren fikri heyecanın gözden kaçırdığı hatalardan koruyabilir.'],
    ['Science and Method, I.3: deliberate work after inspiration', 'Give an insight the patient work of arrangement and explanation. The moment of discovery is followed by the task of making it understandable.', 'Bir kavrayışa düzenleme ve açıklamanın sabırlı emeğini ver. Keşif anını, onu anlaşılır kılma görevi izler.'],
    ['Science and Method, I.3: harmony as an aid to the mind', 'Seek an arrangement in which the whole and its details can be grasped together. Clarity can be both useful and beautiful.', 'Bütünün ve ayrıntıların birlikte kavranabildiği bir düzen ara. Açıklık, aynı anda hem yararlı hem güzel olabilir.'],
  ]),
  ...passages('John Stuart Mill', 'On Liberty', 'Özgürlük Üzerine', 'https://www.gutenberg.org/files/34901/34901-h/34901-h.htm', 'society', [
    ['II: hearing an opposing case from its advocates', 'Hear a different view from someone who sincerely holds it. Understanding their strongest reasons can deepen your understanding of your own.', 'Farklı bir görüşü, ona içtenlikle inanan birinden dinle. En güçlü gerekçelerini anlamak, kendi düşünceni kavrayışını da derinleştirebilir.'],
    ['II: living truth rather than unexamined assent', 'Keep an important conviction alive by understanding its reasons. Repeating familiar words is not the same as knowing why they matter.', 'Önemli bir kanaatini gerekçelerini anlayarak canlı tut. Tanıdık sözleri tekrarlamak, neden önemli olduklarını bilmekle aynı şey değildir.'],
    ['II: partial truths in opposing opinions', 'An opposing opinion may carry a part of the truth you missed. You can learn from that part without accepting everything around it.', 'Karşıt bir görüş, gözden kaçırdığın bir doğru parçasını taşıyabilir. Çevresindeki her şeyi kabul etmeden o parçadan öğrenebilirsin.'],
    ['II: correcting and completing one’s opinion', 'The habit of correcting a judgment can make it more trustworthy. You do not need to pretend infallibility in order to think responsibly.', 'Bir yargıyı düzeltme alışkanlığı, onu daha güvenilir kılabilir. Sorumlulukla düşünmek için yanılmazmış gibi davranman gerekmez.', true],
    ['II: opportunity for truth to reach us', 'Leave a channel through which a better explanation can reach you. Keeping inquiry open is a practical form of intellectual humility.', 'Daha iyi bir açıklamanın sana ulaşabileceği bir yol açık bırak. Araştırmayı açık tutmak, düşüncede alçakgönüllülüğün somut bir biçimidir.'],
    ['III: experiments in living', 'Different ways of living can teach us what human life allows. Give a harmless unfamiliar choice room to show what it can become.', 'Farklı yaşama biçimleri, insan hayatının imkânlarını öğretebilir. Zararı olmayan alışılmadık bir seçime, neye dönüşebileceğini göstermesi için alan aç.', true],
    ['III: interpreting inherited experience', 'Learn from earlier experience while asking whether it fits your circumstances. Respect for a tradition can include thoughtful judgment about its application.', 'Önceki deneyimlerden öğrenirken kendi koşullarına uyup uymadığını sor. Bir geleneğe saygı, onun uygulanışını bilinçle değerlendirmeyi de içerebilir.'],
    ['III: choice exercises human faculties', 'Choosing deliberately exercises capacities that imitation leaves unused. Bring perception, judgment, and your own considered preference into a decision that concerns your life.', 'Bilinçli seçim, taklidin kullanmadığı yetileri çalıştırır. Hayatını ilgilendiren bir karara gözlemini, değerlendirmelerini ve düşünülmüş tercihini kat.'],
    ['III: choosing one’s own plan of life', 'Give your life plan your own serious consideration. Observing, weighing, deciding, and holding to a considered choice are all parts of becoming capable.', 'Hayat planını kendi ciddi değerlendirmenle kur. Gözlemlemek, tartmak, karar vermek ve düşünülmüş seçimine bağlı kalmak, yetkinleşmenin parçalarıdır.'],
    ['III: human nature as a growing tree', 'Your development need not fit a single mechanical pattern. A living person, like a growing tree, needs room to unfold in more than one direction.', 'Gelişimin tek bir mekanik kalıba sığmak zorunda değildir. Yaşayan insan, büyüyen bir ağaç gibi farklı yönlerde gelişecek alana ihtiyaç duyar.'],
    ['III: strong feeling and cultivated conscience', 'Strong feelings can become material for generosity and self-command. Cultivating them thoughtfully matters more than treating all intensity as a fault.', 'Güçlü duygular, cömertliğe ve özdenetime kaynak olabilir. Her yoğunluğu kusur saymak yerine duyguları bilinçle geliştirmek önemlidir.'],
    ['III: choosing under the pressure of conformity', 'Alongside asking what people expect, ask what lets your better capacities grow. Fear of appearing different need not answer every personal question for you.', 'İnsanların beklentisini sorarken iyi yanlarını neyin geliştirdiğini de sor. Farklı görünme korkusu, her kişisel sorunu senin yerine cevaplamasın.', true],
    ['III: originality opening people’s eyes', 'An original contribution may reveal a possibility others could not yet see. Its unfamiliarity alone is not evidence that it has no value.', 'Özgün bir katkı, başkalarının henüz göremediği bir imkânı gösterebilir. Alışılmadık olması, tek başına değersizliğinin kanıtı değildir.', true],
    ['III: pointing out a way without compelling others', 'You can offer a new direction without forcing others to follow. A useful example respects the freedom of the people it hopes to influence.', 'Başkalarını zorlamadan yeni bir yön gösterebilirsin. Yararlı bir örnek, etkilemeyi umduğu insanların özgürlüğüne saygı duyar.'],
    ['III: different conditions for different people’s development', 'The conditions that help another person flourish may not suit you. Take your own needs seriously when choosing a sustainable way of living.', 'Bir başkasını geliştiren koşullar sana uymayabilir. Sürdürebileceğin bir yaşama biçimi seçerken kendi ihtiyaçlarını da ciddiye al.'],
  ]),
  ...passages('Peter Kropotkin', 'Mutual Aid', 'Karşılıklı Yardımlaşma', 'https://www.gutenberg.org/cache/epub/4341/pg4341-images.html', 'society', [
    ['VIII: associations for study and research', 'A shared interest can become a small community of learning. Gathering to study is also a way of making mutual support part of ordinary life.', 'Ortak bir ilgi, küçük bir öğrenme topluluğuna dönüşebilir. Çalışmak için buluşmak, karşılıklı desteği günlük hayatın parçası yapmanın da yoludur.'],
    ['VIII: clubs for the shared enjoyment of life', 'Shared enjoyment can grow into lasting friendship. A simple activity done together may become a place where people feel welcome and supported.', 'Paylaşılan sevinç, kalıcı dostluğa dönüşebilir. Birlikte yapılan basit bir etkinlik, insanların kendini kabul edilmiş ve desteklenmiş hissettiği bir alan olabilir.'],
    ['VIII: naturalists across occupations and social positions', 'Curiosity about nature can put an expert and an amateur beside one another. A common question can begin a relationship beyond differences of status.', 'Doğaya duyulan merak, uzmanla meraklıyı yan yana getirebilir. Ortak bir soru, konum farklılıklarının ötesinde bir ilişkinin başlangıcı olabilir.'],
    ['VIII: intellectual associations in remote towns', 'A small circle of readers or learners can connect a distant place with the wider world. Intellectual life does not belong only to great centers.', 'Küçük bir okuma veya öğrenme çevresi, uzak bir yeri dünyaya bağlayabilir. Düşünce hayatı yalnızca büyük merkezlere ait değildir.'],
    ['VIII: the unambitious voluntary work behind associations', 'Much that sustains a community is quiet, voluntary work. Notice the people who prepare, organize, and help without making themselves the center.', 'Bir topluluğu yaşatan işlerin çoğu sessiz ve gönüllüdür. Kendini merkeze koymadan hazırlayan, düzenleyen ve yardım eden insanları fark et.'],
    ['VIII: educational societies as support for teachers', 'Those who help others learn also need support. A circle of colleagues can make demanding service less lonely and more resourceful.', 'Başkalarının öğrenmesine yardım edenlerin de desteğe ihtiyacı vardır. Bir meslektaş çevresi, zorlayıcı hizmeti daha az yalnız ve daha donanımlı kılabilir.'],
    ['VIII: children protecting one another in neighborhood play', 'Care is visible even in children watching out for one another. Mutual protection can begin with noticing a risk and speaking in time.', 'Birbirini gözeten çocuklarda bile özen görünür. Karşılıklı koruma, bir riski fark edip zamanında seslenmekle başlayabilir.'],
    ['VIII: neighbors supporting mothers and children', 'Support can take the shape of a meal, a household task, or time given to a child. Ordinary help makes care concrete.', 'Destek, bir öğün yemek, evde yapılan bir iş veya bir çocuğa ayrılan zaman olabilir. Sıradan yardım, özeni somutlaştırır.'],
    ['VII: shared agricultural machinery', 'Some useful tools remain out of reach alone but become possible through association. Pooling resources can open a practical opportunity for everyone involved.', 'Bazı yararlı araçlara tek başına ulaşılamazken birlikte ulaşılabilir. Kaynakları birleştirmek, katılan herkes için somut bir imkân açabilir.'],
    ['VII: communal cultivation for people in need', 'A common task can welcome different kinds of contribution. What people produce together can then support someone who has less to give.', 'Ortak bir iş, farklı katkılara yer açabilir. Birlikte üretilen şey, verecek imkânı daha az olan birini de destekleyebilir.'],
    ['VII: testing improved cultivation on a small shared plot', 'A community can try a new method on a modest scale before adopting it widely. Learning together can make improvement both practical and shared.', 'Bir topluluk, yeni yöntemi yaygınlaştırmadan önce küçük ölçekte deneyebilir. Birlikte öğrenmek, gelişimi hem uygulanabilir hem ortak hale getirebilir.'],
    ['VIII: international associations and personal contact', 'Working with people across boundaries can weaken inherited distance. Real acquaintance gives solidarity something firmer than a slogan to stand on.', 'Sınırların ötesindeki insanlarla çalışmak, devralınan uzaklığı azaltabilir. Gerçek tanışıklık, dayanışmaya bir slogandan daha sağlam dayanak verir.'],
    ['Conclusion: progressive individual self-assertion', 'Cooperation need not erase personal initiative. There is room both for mutual support and for a person resisting customs that prevent their development.', 'İşbirliği, kişisel girişimi silmek zorunda değildir. Hem karşılıklı desteğe hem insanın gelişimini engelleyen alışkanlıklara karşı çıkmasına yer vardır.'],
    ['Conclusion: widening the circle of mutual aid', 'Let concern expand beyond the circle in which it first grew. The same impulse that supports a neighbor can reach toward a wider human fellowship.', 'İlgin, ilk büyüdüğü çevrenin ötesine uzansın. Komşuyu destekleyen aynı yöneliş, daha geniş bir insanlık kardeşliğine ulaşabilir.'],
    ['Conclusion: giving beyond strict reciprocity', 'Kindness can go beyond keeping accounts of what is owed. Freely offering more than you expect back gives mutual care a generous form.', 'İyilik, kimin ne borçlu olduğunun hesabını aşabilir. Karşılığında beklediğinden fazlasını gönüllü sunmak, karşılıklı özene cömert bir biçim verir.'],
  ]),
  ...passages('Florence Nightingale', 'Notes on Nursing', 'Hemşirelik Üzerine Notlar', 'https://www.gutenberg.org/cache/epub/17366/pg17366-images.html', 'science', [
    ['XII: encouragement without minimizing suffering', 'Encourage someone without pretending their difficulty is smaller than it is. Honest companionship can respect suffering while still making room for hope.', 'Birini cesaretlendirirken güçlüğünü olduğundan küçük gösterme. Dürüst bir yakınlık, acıya saygı duyarken umuda da yer açabilir.', true],
    ['XII: a real benevolent act rather than repeated advice', 'A true account of help that worked can refresh a weary listener. Sometimes an example of kindness is more welcome than another piece of advice.', 'Gerçekten işe yarayan bir yardımın hikâyesi, yorgun bir dinleyiciyi canlandırabilir. Bazen iyilik örneği, yeni bir öğütten daha hoş karşılanır.'],
    ['XII: interested presence rather than absence of mind', 'Be interested in the person in front of you. Warm company asks for attention, not an endless supply of instruction or solemn words.', 'Karşındaki insanla gerçekten ilgilen. Sıcak bir arkadaşlık, bitmeyen öğütler veya ağır sözlerden önce dikkatini ister.'],
    ['III: communicating absence and return', 'When someone depends on you, tell them clearly what to expect. A considerate explanation can spare them the burden of unnecessary uncertainty.', 'Birisi sana güveniyorsa ne bekleyebileceğini açıkça söyle. Düşünceli bir açıklama, onu gereksiz belirsizliğin yükünden koruyabilir.', true],
    ['V: variety, color, and beautiful objects', 'Do not dismiss a small source of beauty as unimportant. A flower or a pleasant view may matter deeply to someone whose world has become narrow.', 'Küçük bir güzellik kaynağını önemsiz sayma. Bir çiçek veya hoş bir manzara, dünyası daralmış biri için derin değer taşıyabilir.'],
    ['XIII: facts rather than casual opinions', 'Describe what you actually noticed before offering a general judgment. Specific observations give another person something more useful than a confident impression.', 'Genel bir yargı sunmadan önce gerçekten fark ettiğini anlat. Somut gözlemler, karşındakine kendinden emin bir izlenimden daha yararlı bilgi verir.'],
    ['XIII: leading questions and misleading answers', 'Ask a question that leaves room for the real answer. If your wording supplies the conclusion, you may miss what the other person needs to tell you.', 'Gerçek cevaba yer bırakan bir soru sor. Sözlerin sonucu peşinen veriyorsa karşındakinin anlatması gereken şeyi kaçırabilirsin.'],
    ['XIII: learning what and how to observe', 'Attention becomes more useful when you learn what changes matter. Care includes improving your ability to notice, not merely intending to be helpful.', 'Hangi değişikliklerin önemli olduğunu öğrendiğinde dikkatin daha yararlı olur. Özen, yardım niyetinin yanında fark etme becerini geliştirmeyi de içerir.'],
    ['XIII: observation for practical purposes', 'Let noticing lead to appropriate action. Seeing that something needs to change is only part of the responsibility of caring.', 'Fark etmek, uygun bir davranışa yol açsın. Bir şeyin değişmesi gerektiğini görmek, özen göstermenin sorumluluğunun yalnızca bir bölümüdür.'],
    ['XIII, note 33: observation, memory, and truthful reporting', 'Wanting to be truthful does not make every memory accurate. Admit what you did not observe instead of filling the gap with imagination.', 'Doğruyu söylemek istemek, her hatırayı doğru kılmaz. Boşluğu hayalinle doldurmak yerine gözlemlemediğin şeyi kabul et.'],
  ]),
];
